# <glob, relative to the nvim config dir>  <areas...>   (suite.sh --changed)
# A changed file matching no line runs every area. startup and smoke always run under --changed.
init.lua                          startup tools
nvim-pack-lock.json               startup installer lsp format lint treesitter git completion which-key ui editing tools
lua/app/init.lua                  startup tools
lua/app/plugins.lua               startup installer
lua/features/init.lua             startup installer
lua/lsp/buffer.lua                lsp keys which-key
lua/lsp/init.lua                  lsp tools
lua/lsp/watchfiles.lua            lsp tools
lua/lang/*                        lsp tools format lint treesitter editing keys which-key
lua/tools/*                       tools lsp format lint
lua/tools/ux.lua                  ui
lua/ui/*                          ui tools lint
lua/format/*                      format keys
lua/linting/*                     lint keys ui
lua/features/treesitter.lua       treesitter keys which-key
lua/features/git.lua              git keys which-key
lua/features/completion.lua       completion
lua/features/completion_path.lua  completion
lua/keys/*                        keys which-key lsp git lint format treesitter
lua/textobjects/*                 treesitter keys which-key
queries/*                         treesitter editing
lua/features/editing.lua          editing keys which-key
lua/features/diagnostics.lua      ui lsp keys
lua/ui/snacks.lua                 ui keys
lua/features/search.lua           keys editing which-key
lua/features/windows.lua          keys editing
lua/features/folds.lua            editing treesitter
lua/features/lua_dev.lua          editing lsp keys which-key
lua/features/files.lua            keys editing
lua/features/profiling.lua        keys
lua/options.lua                   editing ui
lua/features/lsp_status.lua      keys lsp
lua/lsp/pyrefly.lua               lsp keys
.luarc.json                       smoke
.luacheckrc                       smoke
stylua.toml                       smoke
.editorconfig                     smoke
